function run(){
  // Exact rational arithmetic with BigInt.
  let p = 0n, q = 1n;
  const g = (a, b) => { while (b) [a, b] = [b, a % b]; return a; };
  for (let k = 1n; k <= 99n; k++) { const d = k * (k + 1n); p = p * d + q; q = q * d; const h = g(p, q); p /= h; q /= h; }
  return Number(p) / Number(q);
}
